create or replace view public.finance_card_statement_operational with (security_invoker=true) as select cs.tenant_id,cs.company_id,cs.id statement_id,cs.card_id,cc.name card_name,cs.statement_month,cs.due_date,cs.statement_amount,b.paid_amount,b.remaining_amount,b.payment_status,case when b.payment_status='paid' then 'paid' when cs.due_date<current_date then 'overdue' when cs.due_date=current_date then 'due_today' else b.payment_status end operational_status,greatest(current_date-cs.due_date,0) overdue_days,cc.default_payment_account_id from public.card_statements cs join public.credit_cards cc on cc.tenant_id=cs.tenant_id and cc.company_id=cs.company_id and cc.id=cs.card_id join public.credit_card_statement_balances b on b.statement_id=cs.id;
create or replace view public.finance_card_installment_operational with (security_invoker=true) as select ci.tenant_id,ci.company_id,ci.card_id,cc.name card_name,ci.transaction_id,ct.purchase_date,ct.description,ct.counterparty_name,ct.category_id,ct.cost_center_id,ci.id card_installment_id,ci.installment_number,ci.installment_count,ci.installment_number::text||'/'||ci.installment_count::text installment_label,ci.statement_month,ci.amount,cs.id statement_id,cs.due_date,coalesce(sb.payment_status,'open_statement') statement_payment_status,case when cs.id is null then 'open_statement' when sb.payment_status='paid' then 'paid' when cs.due_date<current_date then 'overdue' when cs.due_date=current_date then 'due_today' else sb.payment_status end operational_status from public.card_installments ci join public.credit_cards cc on cc.tenant_id=ci.tenant_id and cc.company_id=ci.company_id and cc.id=ci.card_id join public.card_transactions ct on ct.tenant_id=ci.tenant_id and ct.company_id=ci.company_id and ct.id=ci.transaction_id left join public.card_statements cs on cs.tenant_id=ci.tenant_id and cs.company_id=ci.company_id and cs.card_id=ci.card_id and cs.statement_month=ci.statement_month left join public.credit_card_statement_balances sb on sb.statement_id=cs.id;
create or replace view public.finance_operational_cards with (security_invoker=true) as select c.tenant_id,c.company_id,c.id card_id,c.name card_name,c.credit_limit,c.status,l.committed_amount,l.available_limit estimated_available_limit,coalesce(sum(case when s.operational_status in ('pending','partial','due_today','overdue') then s.remaining_amount else 0 end),0)::numeric(14,2) open_statement_amount,coalesce(sum(case when s.operational_status='overdue' then s.remaining_amount else 0 end),0)::numeric(14,2) overdue_statement_amount,count(*) filter(where s.operational_status='overdue') overdue_statement_count,min(s.due_date) filter(where s.operational_status in ('pending','partial','due_today','overdue')) next_due_date from public.credit_cards c join public.credit_card_limits l on l.card_id=c.id left join public.finance_card_statement_operational s on s.tenant_id=c.tenant_id and s.company_id=c.company_id and s.card_id=c.id group by c.tenant_id,c.company_id,c.id,c.name,c.credit_limit,c.status,l.committed_amount,l.available_limit;
create or replace view public.finance_operational_overview with (security_invoker=true) as with installments as (select tenant_id,company_id,coalesce(sum(open_amount) filter(where entry_type='expense'),0)::numeric(14,2) payable_open,coalesce(sum(open_amount) filter(where entry_type='expense' and payment_status='overdue'),0)::numeric(14,2) payable_overdue,coalesce(sum(open_amount) filter(where entry_type='income'),0)::numeric(14,2) receivable_open,coalesce(sum(open_amount) filter(where entry_type='income' and payment_status='overdue'),0)::numeric(14,2) receivable_overdue from public.finance_operational_installments group by tenant_id,company_id),cards as (select tenant_id,company_id,coalesce(sum(open_statement_amount),0)::numeric(14,2) card_open,coalesce(sum(overdue_statement_amount),0)::numeric(14,2) card_overdue,coalesce(sum(estimated_available_limit),0)::numeric(14,2) card_available_limit from public.finance_operational_cards group by tenant_id,company_id),accounts as (select tenant_id,company_id,coalesce(sum(current_balance),0)::numeric(14,2) account_balance from public.financial_account_balances where status='active' group by tenant_id,company_id) select c.tenant_id,c.id company_id,coalesce(c.trade_name,c.legal_name) company_name,coalesce(a.account_balance,0)::numeric(14,2) account_balance,coalesce(i.payable_open,0)::numeric(14,2) payable_open,coalesce(i.payable_overdue,0)::numeric(14,2) payable_overdue,coalesce(i.receivable_open,0)::numeric(14,2) receivable_open,coalesce(i.receivable_overdue,0)::numeric(14,2) receivable_overdue,coalesce(cd.card_open,0)::numeric(14,2) card_open,coalesce(cd.card_overdue,0)::numeric(14,2) card_overdue,coalesce(cd.card_available_limit,0)::numeric(14,2) card_available_limit,(coalesce(a.account_balance,0)+coalesce(i.receivable_open,0)-coalesce(i.payable_open,0)-coalesce(cd.card_open,0))::numeric(14,2) operational_net_position from public.companies c left join accounts a on a.tenant_id=c.tenant_id and a.company_id=c.id left join installments i on i.tenant_id=c.tenant_id and i.company_id=c.id left join cards cd on cd.tenant_id=c.tenant_id and cd.company_id=c.id;
create index if not exists card_installments_transaction_fk_idx on public.card_installments(tenant_id,company_id,transaction_id);
create index if not exists card_statement_payments_account_fk_idx on public.card_statement_payments(tenant_id,company_id,account_id);
create index if not exists card_statement_payments_card_fk_idx on public.card_statement_payments(tenant_id,company_id,card_id);
create index if not exists card_transactions_category_fk_idx on public.card_transactions(tenant_id,company_id,category_id);
create index if not exists card_transactions_cost_center_fk_idx on public.card_transactions(tenant_id,company_id,cost_center_id);
create index if not exists credit_cards_payment_account_fk_idx on public.credit_cards(tenant_id,company_id,default_payment_account_id);
comment on view public.finance_card_installment_operational is 'Parcelas de cartão para interface, sempre expondo número/total da parcela.';
comment on view public.finance_operational_overview is 'Consolidação operacional por empresa; pagamento de fatura não é nova despesa.';